            <input type="checkbox" id="mark2"> [ ] 
            <label>Posição 3:</label><br>
            <input type="checkbox" id="mark3"> [ ] 
            <label>Posição 4:</label><br>
            <input type="checkbox" id="mark4"> [ ] 
            <label>Posição 5:</label><br>
            <input type="checkbox" id="mark5"> [ ] 
